        effectiveConfig.jobParamPatches[agentName] &&
        effectiveConfig.jobParamPatches[agentName].customParams;
    var patchedTarget = readContentOutputTarget(patchCustomParams);
    if (patchedTarget) {
        target = patchedTarget;
